import{_ as n,o as r,c as a,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const i="/bilder/suchen-gruppenprozesse/gruppenprozesse-details-zu-faechern-bei-schuelern-aendern.png",t="/bilder/suchen-gruppenprozesse/gruppenprozesse-angaben-zu-faechern-aendern.png",f=JSON.parse('{"title":"Fachdetails für eine Schülergruppe ändern oder leeren","description":"","frontmatter":{"title":"Fachdetails für eine Schülergruppe ändern oder leeren","source_pageid":299,"source_revision":5344},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/details-zu-faechern-bei-schuelern-aendern-gruppenprozesse-faecher.md","filePath":"schild3/suchen-gruppenprozesse/details-zu-faechern-bei-schuelern-aendern-gruppenprozesse-faecher.md"}'),d={name:"schild3/suchen-gruppenprozesse/details-zu-faechern-bei-schuelern-aendern-gruppenprozesse-faecher.md"};function l(h,e,p,c,u,o){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="fachdetails-fur-eine-schulergruppe-andern-oder-leeren" tabindex="-1">Fachdetails für eine Schülergruppe ändern oder leeren <a class="header-anchor" href="#fachdetails-fur-eine-schulergruppe-andern-oder-leeren" aria-label="Permalink to &quot;Fachdetails für eine Schülergruppe ändern oder leeren&quot;">​</a></h1><p>Ändern Sie Angaben bereits vorhandener Fächer, etwa Lehrkraft, Kursart oder Wochen-Zeiteinheiten. Zum gezielten Entfernen von Feldinhalten dient der Reiter Leeren.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-details-zu-faechern-bei-schuelern-aendern.png"><img src="'+i+'" alt="Gruppenprozesse_Details_ändern" loading="lazy"></a></p><p><em>Gruppenprozesse_Details_ändern</em></p><p>Mit dem Aufruf des Gruppenprozesses <strong>Details zu Fächern bei Schülern ändern</strong> erscheint das Eingabefenster, in dem Felder bei existierenden Fächern geändert werden können.</p><p>Ändern Sie zum Beispiel die <em>Lehrkraft</em>, <em>Wochen-Zeiteinheiten</em> oder die <em>Kursart</em> eines Faches.</p><h2 id="_1-fach-und-zielabschnitt-festlegen" tabindex="-1">1. Fach und Zielabschnitt festlegen <a class="header-anchor" href="#_1-fach-und-zielabschnitt-festlegen" aria-label="Permalink to &quot;1. Fach und Zielabschnitt festlegen&quot;">​</a></h2><p>Im Kopfbereich des Fensters sind die Angaben des zu bearbeitenden Faches vorzunehmen.</p><h2 id="_2-angaben-andern-oder-gezielt-leeren" tabindex="-1">2. Angaben ändern oder gezielt leeren <a class="header-anchor" href="#_2-angaben-andern-oder-gezielt-leeren" aria-label="Permalink to &quot;2. Angaben ändern oder gezielt leeren&quot;">​</a></h2><p>Auf der Registerkarte <strong>Ändern</strong> können nun zahlreiche Informationen zu dem ausgewählten Fach bei den ausgewählten Schülern für einen beliebigen zu wählenden Abschnitt geändert werden.</p><p>Auch ein Fach mit bereits eingetragenen Noten kann in ein anderes Fach umgewandelt werden. Die vorhandenen Noten werden dabei für das neue Fach übernommen.</p><p>Die Felder, in die nichts eingetragen wurde, führen nicht zum Löschen der Information.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-angaben-zu-faechern-aendern.png"><img src="'+t+'" alt="Wählen Sie den Reiter Leeren, um Felder zum löschen auszuwählen." loading="lazy"></a></p><p><em>Wählen Sie den Reiter <strong>Leeren</strong>, um Felder zum löschen auszuwählen.</em></p><p>Sie können über den Reiter <strong>Leeren</strong> auch Felder auswählen, die gelöscht werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Details_zu_F%C3%A4chern_bei_Sch%C3%BClern_%C3%A4ndern_(Gruppenprozesse_F%C3%A4cher)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5344.</p>',17)])])}const z=n(d,[["render",l]]);export{f as __pageData,z as default};
